public enum BindingProtocol: Equatable, Hashable {
    
    case http
    case webSocket
    case unsupported





}

#if compiler(>=6)
extension BindingProtocol: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBindingProtocol: FfiConverterRustBuffer {
    typealias SwiftType = BindingProtocol

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BindingProtocol {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .http
        
        case 2: return .webSocket
        
        case 3: return .unsupported
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BindingProtocol, into buf: inout [UInt8]) {
        switch value {
        
        
        case .http:
            writeInt(&buf, Int32(1))
        
        
        case .webSocket:
            writeInt(&buf, Int32(2))
        
        
        case .unsupported:
            writeInt(&buf, Int32(3))
        
        }
    }
}


