public enum GrpcEvent: Equatable, Hashable {
    
    case connected
    case metadataReceived(headers: [KeyValuePair]
    )
    case messageReceived(json: String, hex: String, truncated: Bool
    )
    case streamHalfClosed
    case completed(statusCode: Int32, statusMessage: String, trailers: [KeyValuePair]
    )
    case error(error: String
    )





}

#if compiler(>=6)
extension GrpcEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeGrpcEvent: FfiConverterRustBuffer {
    typealias SwiftType = GrpcEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> GrpcEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .connected
        
        case 2: return .metadataReceived(headers: try FfiConverterSequenceTypeKeyValuePair.read(from: &buf)
        )
        
        case 3: return .messageReceived(json: try FfiConverterString.read(from: &buf), hex: try FfiConverterString.read(from: &buf), truncated: try FfiConverterBool.read(from: &buf)
        )
        
        case 4: return .streamHalfClosed
        
        case 5: return .completed(statusCode: try FfiConverterInt32.read(from: &buf), statusMessage: try FfiConverterString.read(from: &buf), trailers: try FfiConverterSequenceTypeKeyValuePair.read(from: &buf)
        )
        
        case 6: return .error(error: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: GrpcEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case .connected:
            writeInt(&buf, Int32(1))
        
        
        case let .metadataReceived(headers):
            writeInt(&buf, Int32(2))
            FfiConverterSequenceTypeKeyValuePair.write(headers, into: &buf)
            
        
        case let .messageReceived(json,hex,truncated):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(json, into: &buf)
            FfiConverterString.write(hex, into: &buf)
            FfiConverterBool.write(truncated, into: &buf)
            
        
        case .streamHalfClosed:
            writeInt(&buf, Int32(4))
        
        
        case let .completed(statusCode,statusMessage,trailers):
            writeInt(&buf, Int32(5))
            FfiConverterInt32.write(statusCode, into: &buf)
            FfiConverterString.write(statusMessage, into: &buf)
            FfiConverterSequenceTypeKeyValuePair.write(trailers, into: &buf)
            
        
        case let .error(error):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(error, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeGrpcEvent_lift(_ buf: RustBuffer) throws -> GrpcEvent {
    return try FfiConverterTypeGrpcEvent.lift(buf)
}

