    )
    case ConnectionFailed(String
    )
    case NotConnected
    case TlsError(String
    )
    case InvalidConfig(String
    )
    case Timeout(String
    )
    case InternalError(String
    )
    case WebSocketError(String
    )
    case SseError(String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension ReqeastError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeReqeastError: FfiConverterRustBuffer {
    typealias SwiftType = ReqeastError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ReqeastError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .HttpError(
            try FfiConverterString.read(from: &buf)
            )
        case 2: return .ConnectionFailed(
            try FfiConverterString.read(from: &buf)
            )
        case 3: return .NotConnected
        case 4: return .TlsError(
            try FfiConverterString.read(from: &buf)
            )
        case 5: return .InvalidConfig(
            try FfiConverterString.read(from: &buf)
            )
        case 6: return .Timeout(
            try FfiConverterString.read(from: &buf)
            )
        case 7: return .InternalError(
            try FfiConverterString.read(from: &buf)
            )
        case 8: return .WebSocketError(
            try FfiConverterString.read(from: &buf)
            )
        case 9: return .SseError(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ReqeastError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .HttpError(v1):
